import React, { useState, useEffect } from 'react';
import { adminAPI, apiCall } from '../../services/apiService';
import './AllApplications.css';

const AllApplications = () => {
  const [applications, setApplications] = useState([]);
  const [filteredApplications, setFilteredApplications] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [filters, setFilters] = useState({
    status: '',
    vendor: '',
    dateRange: ''
  });
  const [selectedApplication, setSelectedApplication] = useState(null);

  useEffect(() => {
    fetchApplications();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [applications, filters]);

  const fetchApplications = async () => {
    setIsLoading(true);
    setError('');

    const result = await apiCall(adminAPI.getAllApplications);

    if (result.success) {
      setApplications(result.data || []);
    } else {
      setError(result.error);
    }

    setIsLoading(false);
  };

  const applyFilters = () => {
    let filtered = [...applications];

    if (filters.status) {
      filtered = filtered.filter(app => app.status === filters.status);
    }

    if (filters.vendor) {
      filtered = filtered.filter(app => 
        app.vendor?.name?.toLowerCase().includes(filters.vendor.toLowerCase())
      );
    }

    if (filters.dateRange) {
      const now = new Date();
      const filterDate = new Date();
      
      switch (filters.dateRange) {
        case 'today':
          filterDate.setHours(0, 0, 0, 0);
          filtered = filtered.filter(app => new Date(app.createdAt) >= filterDate);
          break;
        case 'week':
          filterDate.setDate(now.getDate() - 7);
          filtered = filtered.filter(app => new Date(app.createdAt) >= filterDate);
          break;
        case 'month':
          filterDate.setMonth(now.getMonth() - 1);
          filtered = filtered.filter(app => new Date(app.createdAt) >= filterDate);
          break;
        default:
          break;
      }
    }

    // Sort by most recent first
    filtered.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    setFilteredApplications(filtered);
  };

  const handleFilterChange = (filterType, value) => {
    setFilters(prev => ({
      ...prev,
      [filterType]: value
    }));
  };

  const clearFilters = () => {
    setFilters({
      status: '',
      vendor: '',
      dateRange: ''
    });
  };

  const handleApplicationAction = async (applicationId, action, comments = '') => {
    setError('');
    setSuccess('');

    const result = await apiCall(adminAPI.updateApplicationStatus, {applicationId, action, comments});

    if (result.success) {
      setSuccess(`Application ${action.toLowerCase()} successfully!`);
      fetchApplications(); // Refresh the list
      setSelectedApplication(null);
    } else {
      setError(result.error);
    }
  };

  const getStatusStats = () => {
    const stats = {
      total: applications.length,
      pending: applications.filter(app => app.status === 'SUBMITTED' || app.status === 'UNDER_REVIEW').length,
      approved: applications.filter(app => app.status === 'APPROVED').length,
      rejected: applications.filter(app => app.status === 'REJECTED').length,
      licensed: applications.filter(app => app.status === 'LICENSED').length
    };
    return stats;
  };

  const getUniqueStatuses = () => {
    return [...new Set(applications.map(app => app.status))];
  };

  if (isLoading) {
    return (
      <div className="loading">
        <div className="loading-spinner"></div>
        Loading applications...
      </div>
    );
  }

  const stats = getStatusStats();

  return (
    <div className="all-applications">
      <div className="page-header">
        <div className="container">
          <h1>All License Applications</h1>
          <p>Manage and review food truck license applications</p>
        </div>
      </div>

      <div className="container">
        {error && (
          <div className="alert alert-error">
            {error}
          </div>
        )}

        {success && (
          <div className="alert alert-success">
            {success}
          </div>
        )}

        {/* Applications Summary */}
        <div className="applications-summary">
          <div className="summary-stats">
            <div className="stat-item">
              <div className="stat-number">{stats.total}</div>
              <div className="stat-label">Total Applications</div>
            </div>
            
            <div className="stat-item">
              <div className="stat-number">{stats.pending}</div>
              <div className="stat-label">Pending Review</div>
            </div>
            
            <div className="stat-item">
              <div className="stat-number">{stats.approved}</div>
              <div className="stat-label">Approved</div>
            </div>

            <div className="stat-item">
              <div className="stat-number">{stats.rejected}</div>
              <div className="stat-label">Rejected</div>
            </div>

            <div className="stat-item">
              <div className="stat-number">{stats.licensed}</div>
              <div className="stat-label">Licensed</div>
            </div>
          </div>
        </div>

        {/* Filters Section */}
        <div className="filters-section">
          <div className="filters-header">
            <h2>Filter Applications</h2>
            <button 
              onClick={clearFilters} 
              className="btn btn-secondary btn-sm"
              disabled={!filters.status && !filters.vendor && !filters.dateRange}
            >
              Clear Filters
            </button>
          </div>

          <div className="filters-grid">
            <div className="filter-group">
              <label className="filter-label">Status</label>
              <select
                value={filters.status}
                onChange={(e) => handleFilterChange('status', e.target.value)}
                className="form-control filter-select"
              >
                <option value="">All Statuses</option>
                {getUniqueStatuses().map(status => (
                  <option key={status} value={status}>{status.replace('_', ' ')}</option>
                ))}
              </select>
            </div>

            <div className="filter-group">
              <label className="filter-label">Vendor</label>
              <input
                type="text"
                value={filters.vendor}
                onChange={(e) => handleFilterChange('vendor', e.target.value)}
                placeholder="Search vendor name..."
                className="form-control filter-input"
              />
            </div>

            <div className="filter-group">
              <label className="filter-label">Date Range</label>
              <select
                value={filters.dateRange}
                onChange={(e) => handleFilterChange('dateRange', e.target.value)}
                className="form-control filter-select"
              >
                <option value="">All Time</option>
                <option value="today">Today</option>
                <option value="week">Last 7 Days</option>
                <option value="month">Last Month</option>
              </select>
            </div>
          </div>
        </div>

        {/* Results Summary */}
        <div className="results-summary">
          <p>
            Showing {filteredApplications.length} of {applications.length} applications
            {(filters.status || filters.vendor || filters.dateRange) && (
              <span className="filter-summary">
                {filters.status && ` with status: ${filters.status.replace('_', ' ')}`}
                {filters.vendor && ` for vendor: ${filters.vendor}`}
                {filters.dateRange && ` from: ${filters.dateRange}`}
              </span>
            )}
          </p>
        </div>

        {/* Applications List */}
        {filteredApplications.length === 0 ? (
          <div className="no-applications">
            <div className="no-app-icon">📋</div>
            <h3>No Applications Found</h3>
            <p>
              {applications.length === 0 
                ? "No applications have been submitted yet."
                : "Try adjusting your filters to see more results."
              }
            </p>
            {(filters.status || filters.vendor || filters.dateRange) && (
              <button onClick={clearFilters} className="btn btn-primary">
                Show All Applications
              </button>
            )}
          </div>
        ) : (
          <div className="applications-list">
            {filteredApplications.map(application => (
              <AdminApplicationCard
                key={application.id}
                application={application}
                onAction={handleApplicationAction}
                onSelect={setSelectedApplication}
              />
            ))}
          </div>
        )}

        {/* Application Details Modal */}
        {selectedApplication && (
          <ApplicationModal
            application={selectedApplication}
            onClose={() => setSelectedApplication(null)}
            onAction={handleApplicationAction}
          />
        )}
      </div>
    </div>
  );
};

const AdminApplicationCard = ({ application, onAction, onSelect }) => {
  const getStatusInfo = (status) => {
    const statusMap = {
      DRAFT: { label: 'Draft', color: 'draft', description: 'Application created but not submitted' },
      SUBMITTED: { label: 'Submitted', color: 'submitted', description: 'Waiting for admin review', actionable: true },
      UNDER_REVIEW: { label: 'Under Review', color: 'review', description: 'Being reviewed by admin', actionable: true },
      APPROVED: { label: 'Approved', color: 'approved', description: 'Application approved' },
      REJECTED: { label: 'Rejected', color: 'rejected', description: 'Application rejected' },
      INSPECTION_SCHEDULED: { label: 'Inspection Scheduled', color: 'scheduled', description: 'Inspection has been scheduled' },
      INSPECTION_COMPLETED: { label: 'Inspection Completed', color: 'completed', description: 'Inspection completed, awaiting results' },
      LICENSED: { label: 'Licensed', color: 'licensed', description: 'License issued successfully' }
    };
    return statusMap[status] || { label: status, color: 'pending', description: 'Unknown status' };
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Not available';
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const statusInfo = getStatusInfo(application.status);
  const canTakeAction = statusInfo.actionable;

  return (
    <div className="admin-application-card">
      <div className="app-header">
        <div className="app-id">
          <h3>Application #{application.id}</h3>
          <span className={`status-badge ${statusInfo.color}`}>
            {statusInfo.label}
          </span>
        </div>
        <div className="app-actions">
          <button
            onClick={() => onSelect(application)}
            className="btn btn-secondary btn-sm"
          >
            View Details
          </button>
          {canTakeAction && (
            <>
              <button
                onClick={() => onAction(application.id, 'APPROVED')}
                className="btn btn-success btn-sm"
              >
                Approve
              </button>
              <button
                onClick={() => onAction(application.id, 'REJECTED')}
                className="btn btn-danger btn-sm"
              >
                Reject
              </button>
            </>
          )}
        </div>
      </div>

      <div className="app-body">
        <div className="vendor-info">
          <div className="vendor-name">
            <strong>Vendor:</strong> {application.vendor?.name}
          </div>
          <div className="vendor-email">
            <strong>Email:</strong> {application.vendor?.user?.email}
          </div>
        </div>

        <div className="app-details">
          <div className="detail-grid">
            <div className="detail-item">
              <span className="detail-label">Created:</span>
              <span className="detail-value">{formatDate(application.createdAt)}</span>
            </div>

            {application.submittedAt && (
              <div className="detail-item">
                <span className="detail-label">Submitted:</span>
                <span className="detail-value">{formatDate(application.submittedAt)}</span>
              </div>
            )}

            {application.reviewedAt && (
              <div className="detail-item">
                <span className="detail-label">Reviewed:</span>
                <span className="detail-value">{formatDate(application.reviewedAt)}</span>
              </div>
            )}
          </div>
        </div>

        <div className="app-status">
          <div className="status-description">
            {statusInfo.description}
          </div>
        </div>
      </div>
    </div>
  );
};

const ApplicationModal = ({ application, onClose, onAction }) => {
  const [comments, setComments] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleAction = async (action) => {
    setIsSubmitting(true);
    await onAction(application.id, action, comments);
    setIsSubmitting(false);
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Application #{application.id}</h2>
          <button onClick={onClose} className="modal-close">×</button>
        </div>

        <div className="modal-body">
          <div className="application-details">
            <div className="detail-section">
              <h3>Vendor Information</h3>
              <p><strong>Name:</strong> {application.vendor?.name}</p>
              <p><strong>Email:</strong> {application.vendor?.user?.email}</p>
              <p><strong>Contact:</strong> {application.vendor?.phoneNumber}</p>
            </div>

            <div className="detail-section">
              <h3>Application Details</h3>
              <p><strong>Status:</strong> {application.status}</p>
              <p><strong>Created:</strong> {new Date(application.createdAt).toLocaleString()}</p>
              {application.submittedAt && (
                <p><strong>Submitted:</strong> {new Date(application.submittedAt).toLocaleString()}</p>
              )}
            </div>

            {application.comments && (
              <div className="detail-section">
                <h3>Previous Comments</h3>
                <p>{application.comments}</p>
              </div>
            )}

            <div className="detail-section">
              <h3>Admin Comments</h3>
              <textarea
                value={comments}
                onChange={(e) => setComments(e.target.value)}
                placeholder="Add comments for this application..."
                className="form-control"
                rows="4"
              />
            </div>
          </div>
        </div>

        <div className="modal-footer">
          <button onClick={onClose} className="btn btn-secondary">
            Close
          </button>
          <button
            onClick={() => handleAction('APPROVED')}
            className="btn btn-success"
            disabled={isSubmitting}
          >
            {isSubmitting ? 'Processing...' : 'Approve'}
          </button>
          <button
            onClick={() => handleAction('REJECTED')}
            className="btn btn-danger"
            disabled={isSubmitting}
          >
            {isSubmitting ? 'Processing...' : 'Reject'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AllApplications;
